/*
 * QUOTES FROM YOUR BOOKS (shown in the sticky note at the bottom of the page).
 * 30 quotes: 10 from each book. The note shows ONE of them on every visit, in random order, and does not
 * repeat a quote until all the others have been shown.
 *
 * One entry per quote:  { slug: 'book-slug', ar: '…', en: '…', de: '…' }
 *   ar = original (Arabic) text,   en / de = translations.
 * All 15 site languages are included (ar, en, de, fr, es, it, pt, nl, pl, sv, ro, el, uk, ru, tr).
 * Do not type the quotation marks («  »  “  ”) - the note adds them.
 * To add more quotes just add more lines; the note adapts automatically.
 */
window.BOOK_QUOTES = [
  /* ---- What Remains of Me  (ما تبقّى مني) ---- */
  { slug: "what-remains-of-me", ar: "صرتُ ما بعد الألم. صرتُ الفراغ الذي ينظر إلى نفسه فلا يرى شيئًا.", en: "I became what comes after the pain. I became the emptiness that looks at itself and sees nothing.", de: "Ich wurde zu dem, was nach dem Schmerz kommt. Ich wurde zur Leere, die sich selbst ansieht und nichts sieht.", fr: "Je suis devenu ce qui vient après la douleur. Je suis devenu le vide qui se regarde et ne voit rien.", es: "Me convertí en lo que viene después del dolor. Me convertí en el vacío que se mira a sí mismo y no ve nada.", it: "Sono diventato ciò che viene dopo il dolore. Sono diventato il vuoto che guarda se stesso e non vede nulla.", pt: "Tornei-me aquilo que vem depois da dor. Tornei-me o vazio que olha para si próprio e não vê nada.", nl: "Ik werd wat na de pijn komt. Ik werd de leegte die naar zichzelf kijkt en niets ziet.", pl: "Stałem się tym, co przychodzi po bólu. Stałem się pustką, która patrzy na siebie i nie widzi nic.", sv: "Jag blev det som kommer efter smärtan. Jag blev tomrummet som ser på sig självt och inte ser något.", ro: "Am devenit ceea ce vine după durere. Am devenit golul care se privește pe sine și nu vede nimic.", el: "Έγινα αυτό που έρχεται μετά τον πόνο. Έγινα το κενό που κοιτάζει τον εαυτό του και δεν βλέπει τίποτα.", uk: "Я став тим, що настає після болю. Я став порожнечею, яка дивиться на себе й нічого не бачить.", ru: "Я стал тем, что наступает после боли. Я стал пустотой, которая смотрит на себя и ничего не видит.", tr: "Acının ardından gelen şey oldum. Kendine bakıp hiçbir şey görmeyen boşluk oldum." },
  { slug: "what-remains-of-me", ar: "أخطر ما في نسيج الأكاذيب أنه يجعلك تشارك في حياكته.", en: "The most dangerous thing about a web of lies is that it makes you take part in weaving it.", de: "Das Gefährlichste an einem Netz aus Lügen ist, dass du selbst am Weben beteiligt wirst.", fr: "Le plus dangereux dans une toile de mensonges, c'est qu'elle te fait participer à son tissage.", es: "Lo más peligroso de una red de mentiras es que te hace participar en su tejido.", it: "La cosa più pericolosa di una rete di bugie è che ti fa partecipare alla sua tessitura.", pt: "O mais perigoso numa teia de mentiras é que te faz participar na sua tecelagem.", nl: "Het gevaarlijkste aan een web van leugens is dat het je laat meeweven.", pl: "Najgroźniejsze w sieci kłamstw jest to, że sprawia, iż sam bierzesz udział w jej tkaniu.", sv: "Det farligaste med ett nät av lögner är att det får dig att delta i att väva det.", ro: "Cel mai periculos lucru la o plasă de minciuni este că te face să participi la țeserea ei.", el: "Το πιο επικίνδυνο σε ένα πλέγμα ψεμάτων είναι ότι σε κάνει να συμμετέχεις στο ύφανσή του.", uk: "Найнебезпечніше в павутині брехні те, що вона змушує тебе брати участь у її плетінні.", ru: "Самое опасное в паутине лжи — то, что она заставляет тебя участвовать в её плетении.", tr: "Yalan ağının en tehlikeli yanı, seni de dokumasına ortak etmesidir." },
  { slug: "what-remains-of-me", ar: "لا أبحث عن عودة، ولا أنتظر شيئًا، فقط… أعيش بما تبقّى مني.", en: "I'm not looking for a return, nor waiting for anything. I just… live on what remains of me.", de: "Ich suche keine Rückkehr und warte auf nichts. Ich lebe nur… von dem, was von mir bleibt.", fr: "Je ne cherche pas de retour, je n'attends rien. Je… vis simplement de ce qui reste de moi.", es: "No busco un regreso ni espero nada. Solo… vivo de lo que queda de mí.", it: "Non cerco un ritorno e non aspetto nulla. Semplicemente… vivo di ciò che resta di me.", pt: "Não procuro um regresso, nem espero nada. Apenas… vivo do que resta de mim.", nl: "Ik zoek geen terugkeer en wacht op niets. Ik… leef gewoon van wat er van mij overblijft.", pl: "Nie szukam powrotu ani niczego nie oczekuję. Po prostu… żyję tym, co ze mnie zostało.", sv: "Jag söker ingen återkomst och väntar inte på något. Jag… lever bara på det som är kvar av mig.", ro: "Nu caut o întoarcere și nu aștept nimic. Doar… trăiesc din ceea ce a rămas din mine.", el: "Δεν ψάχνω επιστροφή ούτε περιμένω κάτι. Απλώς… ζω από ό,τι απέμεινε από μένα.", uk: "Я не шукаю повернення й нічого не чекаю. Просто… живу тим, що від мене залишилося.", ru: "Я не ищу возвращения и ничего не жду. Я просто… живу тем, что от меня осталось.", tr: "Bir dönüş aramıyorum, hiçbir şey de beklemiyorum. Sadece… benden geriye kalanla yaşıyorum." },
  { slug: "what-remains-of-me", ar: "سرق الذات نفسها. سرق مني \"أنا\"، قطعة قطعة، حتى لم يعد هناك \"أنا\" يُسرق.", en: "He stole the self itself. He stole the \"I\" from me, piece by piece, until there was no \"I\" left to steal.", de: "Er stahl das Selbst an sich. Er stahl mir das „Ich“, Stück für Stück, bis kein „Ich“ mehr übrig war, das man stehlen konnte.", fr: "Il a volé le moi lui-même. Il m'a volé le  je , morceau par morceau, jusqu'à ce qu'il ne reste plus de  je  à voler.", es: "Robó el yo mismo. Me robó el yo, pedazo a pedazo, hasta que no quedó ningún yo que robar.", it: "Ha rubato il sé stesso. Mi ha rubato l'io, pezzo dopo pezzo, finché non è rimasto più nessun io da rubare.", pt: "Roubou o próprio eu. Roubou-me o eu, peça a peça, até já não haver nenhum eu para roubar.", nl: "Hij stal het zelf als zodanig. Hij stal het ‘ik’ van mij, stukje voor stukje, tot er geen ‘ik’ meer over was om te stelen.", pl: "Ukradł samo jestestwo. Ukradł mi „ja, kawałek po kawałku, aż nie zostało już żadne „ja do ukradzenia.", sv: "Han stal själva jaget. Han stal jaget från mig, bit för bit, tills det inte fanns något jag kvar att stjäla.", ro: "A furat însuși sinele. Mi-a furat „eul, bucată cu bucată, până când nu a mai rămas niciun „eu de furat.", el: "Έκλεψε το ίδιο το εγώ. Μου έκλεψε το εγώ, κομμάτι κομμάτι, μέχρι που δεν έμεινε κανένα εγώ να κλαπεί.", uk: "Він украв саме єство. Він украв у мене я, шматок за шматком, доки не лишилося жодного я, яке можна було б украсти.", ru: "Он украл само я. Он украл у меня я, кусок за куском, пока не осталось никакого я, которое можно было бы украсть.", tr: "Benliğin kendisini çaldı. Benden beni çaldı, parça parça, çalınacak bir ben kalmayana kadar." },
  { slug: "what-remains-of-me", ar: "ثقب صغير، لكنه كان كافيًا ليدخل منه نور الحقيقة المرّ.", en: "A small hole, but enough for the bitter light of truth to enter.", de: "Ein kleines Loch, aber groß genug, dass das bittere Licht der Wahrheit hindurchfiel.", fr: "Un petit trou, mais assez grand pour laisser entrer l'amère lumière de la vérité.", es: "Un pequeño agujero, pero suficiente para que entrara la amarga luz de la verdad.", it: "Un piccolo foro, ma bastò perché vi entrasse l'amara luce della verità.", pt: "Um pequeno buraco, mas o bastante para que a luz amarga da verdade entrasse.", nl: "Een klein gaatje, maar groot genoeg om het bittere licht van de waarheid binnen te laten.", pl: "Mała dziura, ale wystarczająca, by wpadło przez nią gorzkie światło prawdy.", sv: "Ett litet hål, men tillräckligt för att sanningens bittra ljus skulle komma in.", ro: "O gaură mică, dar de ajuns ca lumina amară a adevărului să pătrundă.", el: "Μια μικρή τρύπα, αλλά αρκετή για να μπει το πικρό φως της αλήθειας.", uk: "Маленька дірка, але достатня, щоб крізь неї проникло гірке світло правди.", ru: "Маленькая дыра, но достаточная, чтобы в неё проник горький свет правды.", tr: "Küçük bir delik, ama gerçeğin acı ışığının içeri girmesine yetecek kadar." },
  { slug: "what-remains-of-me", ar: "الوهم الدائم هو أخطر أنواع الخداع، لأنه يأخذ سنوات حياتك ويبيعها لك على أنها استثمار.", en: "Permanent illusion is the most dangerous kind of deception, because it takes the years of your life and sells them back to you as an investment.", de: "Die dauerhafte Illusion ist die gefährlichste Art der Täuschung, denn sie nimmt die Jahre deines Lebens und verkauft sie dir als Investition.", fr: "L'illusion durable est la plus dangereuse des tromperies, car elle prend les années de ta vie et te les revend comme un investissement.", es: "La ilusión permanente es la forma más peligrosa de engaño, porque toma los años de tu vida y te los vende de vuelta como una inversión.", it: "L'illusione permanente è il tipo di inganno più pericoloso, perché prende gli anni della tua vita e te li rivende come un investimento.", pt: "A ilusão permanente é o tipo mais perigoso de engano, porque pega nos anos da tua vida e vende-tos de volta como um investimento.", nl: "Blijvende illusie is de gevaarlijkste vorm van bedrog, want ze neemt de jaren van je leven en verkoopt ze je terug als een investering.", pl: "Trwała iluzja to najniebezpieczniejszy rodzaj oszustwa, bo zabiera lata twojego życia i sprzedaje ci je z powrotem jako inwestycję.", sv: "Bestående illusion är den farligaste sortens bedrägeri, för den tar åren av ditt liv och säljer tillbaka dem till dig som en investering.", ro: "Iluzia permanentă este cel mai periculos fel de înșelăciune, pentru că îți ia anii vieții și ți-i vinde înapoi drept investiție.", el: "Η μόνιμη ψευδαίσθηση είναι το πιο επικίνδυνο είδος εξαπάτησης, γιατί παίρνει τα χρόνια της ζωής σου και σου τα πουλά πίσω ως επένδυση.", uk: "Постійна ілюзія — найнебезпечніший різновид обману, бо вона забирає роки твого життя й продає їх тобі назад як інвестицію.", ru: "Постоянная иллюзия — самый опасный вид обмана, ведь она забирает годы твоей жизни и продаёт их тебе обратно как инвестицию.", tr: "Kalıcı yanılsama, en tehlikeli aldatma türüdür; çünkü hayatının yıllarını alır ve sana yatırım diye geri satar." },
  { slug: "what-remains-of-me", ar: "فأصبح الفرح نفسه عبئًا، والراحة شعورًا بالخيانة.", en: "So joy itself became a burden, and rest a feeling of betrayal.", de: "So wurde selbst die Freude zur Last und die Ruhe zu einem Gefühl von Verrat.", fr: "Ainsi, la joie elle-même est devenue un fardeau, et le repos un sentiment de trahison.", es: "Así, hasta la alegría se volvió una carga, y el descanso, una sensación de traición.", it: "Così persino la gioia è diventata un peso, e il riposo un senso di tradimento.", pt: "Assim, até a alegria se tornou um fardo, e o descanso, uma sensação de traição.", nl: "Zo werd zelfs vreugde een last, en rust een gevoel van verraad.", pl: "Tak więc nawet radość stała się ciężarem, a odpoczynek – poczuciem zdrady.", sv: "Så blev till och med glädjen en börda, och vilan en känsla av svek.", ro: "Așa că până și bucuria a devenit o povară, iar odihna – un sentiment de trădare.", el: "Έτσι ακόμη και η χαρά έγινε βάρος, και η ανάπαυση αίσθημα προδοσίας.", uk: "Тож навіть радість стала тягарем, а спокій — відчуттям зради.", ru: "Так что сама радость стала бременем, а покой — чувством предательства.", tr: "Böylece sevincin kendisi bir yüke, dinlenme ise bir ihanet duygusuna dönüştü." },
  { slug: "what-remains-of-me", ar: "كنتُ أفضّل أن أعيش في الكذبة الجميلة، على أن أواجه الواقع المرعب.", en: "I preferred to live in the beautiful lie rather than face the terrifying reality.", de: "Ich zog es vor, in der schönen Lüge zu leben, statt der schrecklichen Wirklichkeit ins Auge zu sehen.", fr: "Je préférais vivre dans le beau mensonge plutôt que d'affronter la réalité terrifiante.", es: "Prefería vivir en la hermosa mentira antes que enfrentar la aterradora realidad.", it: "Preferivo vivere nella bella bugia piuttosto che affrontare la realtà terrificante.", pt: "Preferia viver na bela mentira a enfrentar a realidade aterradora.", nl: "Ik leefde liever in de mooie leugen dan de angstaanjagende werkelijkheid onder ogen te zien.", pl: "Wolałem żyć w pięknym kłamstwie, niż stanąć twarzą w twarz z przerażającą rzeczywistością.", sv: "Jag föredrog att leva i den vackra lögnen framför att möta den skrämmande verkligheten.", ro: "Preferam să trăiesc în minciuna frumoasă decât să înfrunt realitatea înspăimântătoare.", el: "Προτιμούσα να ζω στο όμορφο ψέμα παρά να αντιμετωπίσω την τρομακτική πραγματικότητα.", uk: "Я волів жити в прекрасній брехні, ніж зустрітися з жахливою реальністю.", ru: "Я предпочитал жить в прекрасной лжи, лишь бы не встречаться с ужасающей реальностью.", tr: "Dehşet verici gerçekle yüzleşmektense güzel yalanın içinde yaşamayı tercih ediyordum." },
  { slug: "what-remains-of-me", ar: "العدم ليس غيابًا. العدم هو حضور الغياب.", en: "Nothingness is not absence. Nothingness is the presence of absence.", de: "Das Nichts ist keine Abwesenheit. Das Nichts ist die Anwesenheit der Abwesenheit.", fr: "Le néant n'est pas une absence. Le néant est la présence de l'absence.", es: "La nada no es ausencia. La nada es la presencia de la ausencia.", it: "Il nulla non è assenza. Il nulla è la presenza dell'assenza.", pt: "O nada não é ausência. O nada é a presença da ausência.", nl: "Het niets is geen afwezigheid. Het niets is de aanwezigheid van afwezigheid.", pl: "Nicość to nie nieobecność. Nicość to obecność nieobecności.", sv: "Intet är inte frånvaro. Intet är frånvarons närvaro.", ro: "Neantul nu este absență. Neantul este prezența absenței.", el: "Το μηδέν δεν είναι απουσία. Το μηδέν είναι η παρουσία της απουσίας.", uk: "Ніщо — це не відсутність. Ніщо — це присутність відсутності.", ru: "Небытие — это не отсутствие. Небытие — это присутствие отсутствия.", tr: "Hiçlik yokluk değildir. Hiçlik, yokluğun varlığıdır." },
  { slug: "what-remains-of-me", ar: "أن تكون موجودًا، ولا تكون.", en: "To be present, and yet not be.", de: "Da zu sein – und doch nicht zu sein.", fr: "Être là, et pourtant ne pas être.", es: "Estar presente y, sin embargo, no estar.", it: "Essere presenti, eppure non essere.", pt: "Estar presente e, no entanto, não estar.", nl: "Aanwezig zijn en toch niet bestaan.", pl: "Być obecnym, a jednak nie być.", sv: "Att vara närvarande, och ändå inte vara.", ro: "Să fii prezent și totuși să nu fii.", el: "Να είσαι παρών, και όμως να μην είσαι.", uk: "Бути присутнім і водночас не бути.", ru: "Быть здесь — и всё же не быть.", tr: "Var olmak ve yine de var olmamak." },
  /* ---- Beyond the Silence  (ما وراء الصمت) ---- */
  { slug: "beyond-the-silence", ar: "أخطر ما يفعله الخذلان أنه لا يكسر القلب فجأة، بل يسحب منك الحياة على هيئة تفاصيل صغيرة.", en: "The most dangerous thing about being let down is that it does not break the heart suddenly, but draws the life out of you in small details.", de: "Das Gefährlichste am Im-Stich-gelassen-Werden ist, dass es das Herz nicht plötzlich bricht, sondern dir das Leben in kleinen Details entzieht.", fr: "Le plus dangereux dans la déception, c'est qu'elle ne brise pas le cœur d'un coup, mais t'enlève la vie par petits détails.", es: "Lo más peligroso de la decepción es que no rompe el corazón de golpe, sino que te va quitando la vida en pequeños detalles.", it: "La cosa più pericolosa della delusione è che non spezza il cuore all'improvviso, ma ti sottrae la vita in piccoli dettagli.", pt: "O mais perigoso da deceção é que não parte o coração de repente, mas vai-te tirando a vida em pequenos detalhes.", nl: "Het gevaarlijkste aan teleurstelling is dat ze het hart niet plotseling breekt, maar je het leven ontneemt in kleine details.", pl: "Najgroźniejsze w zawodzie jest to, że nie łamie serca nagle, lecz odbiera ci życie w drobnych szczegółach.", sv: "Det farligaste med svek är att det inte krossar hjärtat plötsligt, utan drar livet ur dig i små detaljer.", ro: "Cel mai periculos lucru la dezamăgire este că nu îți frânge inima dintr-odată, ci îți trage viața din tine în mici detalii.", el: "Το πιο επικίνδυνο στην απογοήτευση είναι ότι δεν σπάει την καρδιά ξαφνικά, αλλά σου αποσπά τη ζωή σε μικρές λεπτομέρειες.", uk: "Найнебезпечніше в розчаруванні те, що воно не ламає серце раптово, а витягує з тебе життя дрібними подробицями.", ru: "Самое опасное в разочаровании то, что оно не разбивает сердце внезапно, а вытягивает из тебя жизнь мелкими деталями.", tr: "Hayal kırıklığının en tehlikeli yanı, kalbi birdenbire kırmaması, hayatı senden küçük ayrıntılar halinde çekip almasıdır." },
  { slug: "beyond-the-silence", ar: "الإنسان حين يمنح أحدهم مكانة أعلى من حقيقته، يبدأ بخسارة نفسه دون أن يشعر.", en: "When a person gives someone a place higher than their reality, he begins to lose himself without noticing.", de: "Wenn ein Mensch jemandem einen höheren Platz einräumt, als dieser in Wahrheit verdient, beginnt er, sich selbst zu verlieren, ohne es zu merken.", fr: "Quand on accorde à quelqu'un une place plus haute que sa réalité, on commence à se perdre sans s'en apercevoir.", es: "Cuando una persona da a alguien un lugar más alto que su realidad, empieza a perderse a sí misma sin darse cuenta.", it: "Quando una persona concede a qualcuno un posto più alto della sua realtà, comincia a perdere sé stessa senza accorgersene.", pt: "Quando alguém dá a outra pessoa um lugar mais alto do que a sua realidade, começa a perder-se a si próprio sem dar por isso.", nl: "Wanneer iemand een ander een hogere plaats geeft dan diens werkelijkheid, begint hij zichzelf te verliezen zonder het te merken.", pl: "Gdy człowiek daje komuś miejsce wyższe niż jego rzeczywistość, zaczyna tracić samego siebie, nie zauważając tego.", sv: "När en människa ger någon en högre plats än dennes verklighet, börjar hon förlora sig själv utan att märka det.", ro: "Când un om dă cuiva un loc mai înalt decât realitatea lui, începe să se piardă pe sine fără să observe.", el: "Όταν ένας άνθρωπος δίνει σε κάποιον θέση ψηλότερη από την πραγματικότητά του, αρχίζει να χάνει τον εαυτό του χωρίς να το καταλαβαίνει.", uk: "Коли людина дає комусь місце вище, ніж його реальність, вона починає втрачати себе, сама того не помічаючи.", ru: "Когда человек отводит кому-то место выше его реальности, он начинает терять себя, сам того не замечая.", tr: "İnsan birine gerçeğinden daha yüksek bir yer verdiğinde, fark etmeden kendini kaybetmeye başlar." },
  { slug: "beyond-the-silence", ar: "ما وراء الصمت ليس فراغًا كما يظنون، بل عالم كامل من المعارك الخفية والذكريات الثقيلة.", en: "What lies beyond the silence is not emptiness, as they think, but a whole world of hidden battles and heavy memories.", de: "Was jenseits der Stille liegt, ist keine Leere, wie sie meinen, sondern eine ganze Welt aus verborgenen Kämpfen und schweren Erinnerungen.", fr: "Ce qui se trouve au-delà du silence n'est pas du vide, comme ils le pensent, mais tout un monde de batailles cachées et de lourds souvenirs.", es: "Lo que hay más allá del silencio no es vacío, como piensan, sino todo un mundo de batallas ocultas y recuerdos pesados.", it: "Ciò che si trova oltre il silenzio non è vuoto, come pensano, ma un intero mondo di battaglie nascoste e ricordi pesanti.", pt: "O que está para lá do silêncio não é vazio, como pensam, mas um mundo inteiro de batalhas ocultas e memórias pesadas.", nl: "Wat voorbij de stilte ligt is geen leegte, zoals ze denken, maar een hele wereld van verborgen gevechten en zware herinneringen.", pl: "To, co leży poza ciszą, nie jest pustką, jak sądzą, lecz całym światem ukrytych walk i ciężkich wspomnień.", sv: "Det som ligger bortom tystnaden är inte tomhet, som de tror, utan en hel värld av dolda strider och tunga minnen.", ro: "Ceea ce se află dincolo de tăcere nu este gol, cum cred ei, ci o lume întreagă de bătălii ascunse și amintiri grele.", el: "Αυτό που βρίσκεται πέρα από τη σιωπή δεν είναι κενό, όπως νομίζουν, αλλά ένας ολόκληρος κόσμος κρυφών μαχών και βαριών αναμνήσεων.", uk: "Те, що лежить за межами тиші, — це не порожнеча, як вони думають, а цілий світ прихованих битв і важких спогадів.", ru: "То, что лежит за пределами тишины, — не пустота, как они думают, а целый мир скрытых битв и тяжёлых воспоминаний.", tr: "Sessizliğin ötesinde olan, sandıkları gibi boşluk değil; gizli savaşlardan ve ağır anılardan oluşan koca bir dünyadır." },
  { slug: "beyond-the-silence", ar: "النجاة ليست في أن يبقى الجميع معك، بل في أن تبقى أنت دون أن تضيع.", en: "Survival is not that everyone stays with you, but that you stay — without being lost.", de: "Rettung heißt nicht, dass alle bei dir bleiben, sondern dass du bleibst, ohne dich zu verlieren.", fr: "Survivre, ce n'est pas que tout le monde reste avec toi, mais que tu restes, sans te perdre.", es: "Sobrevivir no es que todos se queden contigo, sino que te quedes tú, sin perderte.", it: "Salvarsi non significa che tutti restino con te, ma che resti tu, senza perderti.", pt: "Sobreviver não é que todos fiquem contigo, mas que fiques tu, sem te perderes.", nl: "Overleven is niet dat iedereen bij je blijft, maar dat jij blijft — zonder jezelf te verliezen.", pl: "Ocalenie nie polega na tym, że wszyscy przy tobie zostają, ale na tym, że ty zostajesz – nie gubiąc się.", sv: "Att överleva är inte att alla stannar hos dig, utan att du stannar – utan att gå förlorad.", ro: "A supraviețui nu înseamnă că toți rămân cu tine, ci că rămâi tu – fără să te pierzi.", el: "Η σωτηρία δεν είναι να μείνουν όλοι μαζί σου, αλλά να μείνεις εσύ, χωρίς να χαθείς.", uk: "Вижити — це не коли всі залишаються з тобою, а коли залишаєшся ти — не втративши себе.", ru: "Спастись — значит не то, что все остаются с тобой, а то, что остаёшься ты, не потеряв себя.", tr: "Kurtuluş, herkesin seninle kalması değil; senin kendini kaybetmeden kalmandır." },
  { slug: "beyond-the-silence", ar: "فالناس يرون النتيجة فقط، ولا يرون الحروب التي سبقتها.", en: "People see only the result, not the wars that came before it.", de: "Die Menschen sehen nur das Ergebnis, nicht die Kriege, die ihm vorausgingen.", fr: "Les gens ne voient que le résultat, pas les guerres qui l'ont précédé.", es: "La gente solo ve el resultado, no las guerras que lo precedieron.", it: "Le persone vedono solo il risultato, non le guerre che lo hanno preceduto.", pt: "As pessoas só veem o resultado, não as guerras que o precederam.", nl: "Mensen zien alleen het resultaat, niet de oorlogen die eraan voorafgingen.", pl: "Ludzie widzą tylko wynik, nie widzą wojen, które go poprzedziły.", sv: "Människor ser bara resultatet, inte krigen som kom före.", ro: "Oamenii văd doar rezultatul, nu și războaiele care l-au precedat.", el: "Οι άνθρωποι βλέπουν μόνο το αποτέλεσμα, όχι τους πολέμους που προηγήθηκαν.", uk: "Люди бачать лише результат, а не війни, що йому передували.", ru: "Люди видят только результат, а не войны, которые ему предшествовали.", tr: "İnsanlar yalnızca sonucu görür, ondan önceki savaşları görmez." },
  { slug: "beyond-the-silence", ar: "الغائب يؤلم مرة، أما الحاضر ببرود فيؤلم كل يوم.", en: "The one who is gone hurts once; the one who is present but cold hurts every day.", de: "Wer fehlt, tut einmal weh; wer da ist, aber kalt bleibt, tut jeden Tag weh.", fr: "Celui qui est parti fait mal une fois ; celui qui est là mais froid fait mal chaque jour.", es: "El que se ha ido duele una vez; el que está presente pero frío duele cada día.", it: "Chi se n'è andato fa male una volta; chi è presente ma freddo fa male ogni giorno.", pt: "Quem partiu dói uma vez; quem está presente mas frio dói todos os dias.", nl: "Wie weg is, doet één keer pijn; wie er is maar kil blijft, doet elke dag pijn.", pl: "Ten, kogo nie ma, boli raz; ten, kto jest, ale zimny, boli każdego dnia.", sv: "Den som är borta gör ont en gång; den som är där men kall gör ont varje dag.", ro: "Cel care a plecat doare o dată; cel care este prezent, dar rece, doare în fiecare zi.", el: "Αυτός που λείπει πονά μία φορά· αυτός που είναι εδώ αλλά ψυχρός πονά κάθε μέρα.", uk: "Той, кого немає, болить один раз; той, хто поруч, але холодний, болить щодня.", ru: "Тот, кого нет, ранит один раз; тот, кто рядом, но холоден, ранит каждый день.", tr: "Giden bir kez acıtır; yanında olup soğuk duran her gün acıtır." },
  { slug: "beyond-the-silence", ar: "ليس صمت الحزن، بل صمت الإدراك؛ ذلك النوع من الهدوء الذي يأتي بعد أن تفهم الناس أكثر مما يجب.", en: "Not the silence of sadness, but the silence of realization — the kind of calm that comes after you have understood people more than you should.", de: "Nicht das Schweigen der Trauer, sondern das Schweigen der Erkenntnis – jene Ruhe, die kommt, nachdem du die Menschen besser verstanden hast, als gut ist.", fr: "Non pas le silence de la tristesse, mais le silence de la lucidité — ce calme qui vient après avoir compris les gens plus qu'il ne faudrait.", es: "No el silencio de la tristeza, sino el silencio de la comprensión: esa calma que llega después de haber entendido a la gente más de lo debido.", it: "Non il silenzio della tristezza, ma il silenzio della consapevolezza: quella calma che arriva dopo aver capito le persone più di quanto si dovrebbe.", pt: "Não o silêncio da tristeza, mas o silêncio da perceção — aquela calma que chega depois de teres compreendido as pessoas mais do que devias.", nl: "Niet de stilte van verdriet, maar de stilte van inzicht — de kalmte die komt nadat je mensen beter hebt begrepen dan goed voor je is.", pl: "Nie cisza smutku, lecz cisza zrozumienia – ten rodzaj spokoju, który przychodzi, gdy zrozumiesz ludzi bardziej, niż powinieneś.", sv: "Inte sorgens tystnad, utan insiktens – den sortens lugn som kommer efter att du förstått människor mer än du borde.", ro: "Nu tăcerea tristeții, ci tăcerea înțelegerii – acel fel de calm care vine după ce ai înțeles oamenii mai mult decât ar trebui.", el: "Όχι η σιωπή της λύπης, αλλά η σιωπή της συνειδητοποίησης — το είδος της γαλήνης που έρχεται όταν έχεις καταλάβει τους ανθρώπους περισσότερο απ' όσο έπρεπε.", uk: "Не мовчання смутку, а мовчання усвідомлення — той спокій, що приходить, коли ти зрозумів людей більше, ніж слід.", ru: "Не молчание печали, а молчание осознания — тот покой, что приходит, когда ты понял людей больше, чем следовало.", tr: "Hüznün sessizliği değil, idrakin sessizliği — insanları olması gerekenden fazla anladıktan sonra gelen o dinginlik." },
  { slug: "beyond-the-silence", ar: "بعض الأبواب أُغلقت داخلي إلى الأبد. ليس غضبًا، بل لأنني تعبت من إعادة الأشياء المكسورة إلى أماكنها القديمة.", en: "Some doors inside me have closed forever. Not out of anger, but because I grew tired of putting broken things back in their old places.", de: "Manche Türen in mir sind für immer geschlossen. Nicht aus Zorn, sondern weil ich es leid war, zerbrochene Dinge an ihre alten Plätze zurückzustellen.", fr: "Certaines portes en moi se sont fermées pour toujours. Non par colère, mais parce que j'étais las de remettre les choses brisées à leur ancienne place.", es: "Algunas puertas dentro de mí se han cerrado para siempre. No por rabia, sino porque me cansé de devolver las cosas rotas a sus viejos lugares.", it: "Alcune porte dentro di me si sono chiuse per sempre. Non per rabbia, ma perché ero stanco di rimettere le cose rotte ai loro vecchi posti.", pt: "Algumas portas dentro de mim fecharam-se para sempre. Não por raiva, mas porque me cansei de pôr as coisas partidas nos seus lugares antigos.", nl: "Sommige deuren in mij zijn voorgoed dicht. Niet uit woede, maar omdat ik het beu was kapotte dingen terug te zetten op hun oude plek.", pl: "Niektóre drzwi we mnie zamknęły się na zawsze. Nie ze złości, lecz dlatego, że zmęczyło mnie odkładanie zepsutych rzeczy na dawne miejsca.", sv: "Vissa dörrar inom mig har stängts för alltid. Inte av vrede, utan för att jag blev trött på att ställa tillbaka trasiga saker på sina gamla platser.", ro: "Unele uși din mine s-au închis pentru totdeauna. Nu de furie, ci pentru că m-am săturat să pun lucrurile sparte la locurile lor vechi.", el: "Μερικές πόρτες μέσα μου έκλεισαν για πάντα. Όχι από θυμό, αλλά επειδή κουράστηκα να βάζω τα σπασμένα πράγματα στις παλιές τους θέσεις.", uk: "Деякі двері всередині мене зачинилися назавжди. Не з гніву, а тому, що я втомився повертати зламані речі на їхні старі місця.", ru: "Некоторые двери во мне закрылись навсегда. Не из гнева, а потому, что я устал возвращать сломанные вещи на их прежние места.", tr: "İçimdeki bazı kapılar sonsuza dek kapandı. Öfkeden değil, kırık şeyleri eski yerlerine koymaktan yorulduğum için." },
  { slug: "beyond-the-silence", ar: "هذه الندوب التي أحملها الآن ليست علامة ضعف، بل أوسمة نجاة.", en: "These scars I carry now are not a sign of weakness, but medals of survival.", de: "Diese Narben, die ich jetzt trage, sind kein Zeichen von Schwäche, sondern Orden des Überlebens.", fr: "Ces cicatrices que je porte maintenant ne sont pas un signe de faiblesse, mais des médailles de survie.", es: "Estas cicatrices que ahora llevo no son señal de debilidad, sino medallas de supervivencia.", it: "Queste cicatrici che porto ora non sono un segno di debolezza, ma medaglie di sopravvivenza.", pt: "Estas cicatrizes que agora carrego não são sinal de fraqueza, mas medalhas de sobrevivência.", nl: "Deze littekens die ik nu draag zijn geen teken van zwakte, maar onderscheidingen van overleving.", pl: "Te blizny, które teraz noszę, nie są oznaką słabości, lecz medalami przetrwania.", sv: "De här ärren jag bär nu är inget tecken på svaghet, utan medaljer för överlevnad.", ro: "Aceste cicatrici pe care le port acum nu sunt un semn de slăbiciune, ci medalii de supraviețuire.", el: "Αυτές οι ουλές που κουβαλώ τώρα δεν είναι σημάδι αδυναμίας, αλλά μετάλλια επιβίωσης.", uk: "Ці шрами, що я нині ношу, — не ознака слабкості, а медалі виживання.", ru: "Эти шрамы, которые я теперь ношу, — не знак слабости, а медали выживания.", tr: "Şimdi taşıdığım bu yara izleri bir zayıflık işareti değil, hayatta kalma madalyalarıdır." },
  { slug: "beyond-the-silence", ar: "الصمت أحيانًا يحمي الإنسان أكثر من الكلام.", en: "Silence sometimes protects a person more than words do.", de: "Schweigen schützt den Menschen manchmal mehr als Worte.", fr: "Le silence protège parfois davantage que les mots.", es: "El silencio a veces protege más a una persona que las palabras.", it: "A volte il silenzio protegge una persona più delle parole.", pt: "O silêncio, por vezes, protege uma pessoa mais do que as palavras.", nl: "Stilte beschermt een mens soms meer dan woorden.", pl: "Cisza czasem chroni człowieka bardziej niż słowa.", sv: "Tystnad skyddar ibland en människa mer än ord.", ro: "Tăcerea îl protejează uneori pe om mai mult decât cuvintele.", el: "Η σιωπή μερικές φορές προστατεύει τον άνθρωπο περισσότερο από τα λόγια.", uk: "Мовчання іноді захищає людину більше, ніж слова.", ru: "Молчание порой защищает человека больше, чем слова.", tr: "Sessizlik bazen insanı sözden daha çok korur." },
  /* ---- I Am Not Innocent  (لست بريئًا) ---- */
  { slug: "i-am-not-innocent", ar: "نحن لا نرى أنفسنا كما نحن. نرى أنفسنا كما نستطيع احتمال رؤيتها.", en: "We do not see ourselves as we are. We see ourselves as we can bear to see ourselves.", de: "Wir sehen uns nicht so, wie wir sind. Wir sehen uns so, wie wir es ertragen können, uns zu sehen.", fr: "Nous ne nous voyons pas tels que nous sommes. Nous nous voyons tels que nous pouvons supporter de nous voir.", es: "No nos vemos como somos. Nos vemos como somos capaces de soportar vernos.", it: "Non vediamo noi stessi come siamo. Ci vediamo come riusciamo a sopportare di vederci.", pt: "Não nos vemos como somos. Vemo-nos como conseguimos suportar ver-nos.", nl: "We zien onszelf niet zoals we zijn. We zien onszelf zoals we het kunnen verdragen onszelf te zien.", pl: "Nie widzimy siebie takimi, jacy jesteśmy. Widzimy siebie takimi, jakimi jesteśmy w stanie znieść swój widok.", sv: "Vi ser oss inte som vi är. Vi ser oss som vi står ut med att se oss.", ro: "Nu ne vedem așa cum suntem. Ne vedem așa cum putem îndura să ne vedem.", el: "Δεν βλέπουμε τους εαυτούς μας όπως είμαστε. Τους βλέπουμε όπως αντέχουμε να τους βλέπουμε.", uk: "Ми бачимо себе не такими, якими є. Ми бачимо себе такими, якими здатні витримати себе бачити.", ru: "Мы видим себя не такими, какие мы есть. Мы видим себя такими, какими способны вынести себя видеть.", tr: "Kendimizi olduğumuz gibi görmeyiz. Kendimizi görmeye katlanabildiğimiz gibi görürüz." },
  { slug: "i-am-not-innocent", ar: "نحن نحاكم الآخرين على ما فعلوه. لكننا نحاكم أنفسنا على ما كنا ننوي فعله.", en: "We judge others by what they did. But we judge ourselves by what we meant to do.", de: "Andere beurteilen wir nach dem, was sie getan haben. Uns selbst beurteilen wir nach dem, was wir tun wollten.", fr: "Nous jugeons les autres sur ce qu'ils ont fait. Mais nous nous jugeons sur ce que nous avions l'intention de faire.", es: "Juzgamos a los demás por lo que hicieron. Pero nos juzgamos a nosotros mismos por lo que pretendíamos hacer.", it: "Giudichiamo gli altri per ciò che hanno fatto. Ma giudichiamo noi stessi per ciò che intendevamo fare.", pt: "Julgamos os outros pelo que fizeram. Mas julgamo-nos a nós próprios pelo que pretendíamos fazer.", nl: "Anderen beoordelen we op wat ze deden. Onszelf beoordelen we op wat we van plan waren te doen.", pl: "Innych oceniamy po tym, co zrobili. Siebie oceniamy po tym, co zamierzaliśmy zrobić.", sv: "Andra dömer vi efter vad de gjorde. Oss själva dömer vi efter vad vi avsåg att göra.", ro: "Îi judecăm pe alții după ce au făcut. Dar ne judecăm pe noi înșine după ce intenționam să facem.", el: "Κρίνουμε τους άλλους γι' αυτό που έκαναν. Αλλά κρίνουμε τους εαυτούς μας γι' αυτό που σκοπεύαμε να κάνουμε.", uk: "Інших ми судимо за те, що вони зробили. Але себе судимо за те, що мали намір зробити.", ru: "Других мы судим по тому, что они сделали. А себя — по тому, что собирались сделать.", tr: "Başkalarını yaptıklarına göre yargılarız. Ama kendimizi yapmayı niyet ettiklerimize göre yargılarız." },
  { slug: "i-am-not-innocent", ar: "فالإِنسان لا يعيش داخل الحقيقة كاملة، بل يعيش داخل الرواية التي يكتبها عن نفسه. رواية يكون فيها غالبًا الضحية، أو المظلوم، أو صاحب الحق.", en: "A person does not live inside the whole truth, but inside the story he writes about himself — a story in which he is usually the victim, the wronged one, the one who is right.", de: "Der Mensch lebt nicht in der ganzen Wahrheit, sondern in der Geschichte, die er über sich selbst schreibt – einer Geschichte, in der er meistens das Opfer ist, der Benachteiligte, derjenige, der im Recht ist.", fr: "L'être humain ne vit pas dans la vérité entière, mais dans le récit qu'il écrit sur lui-même — un récit où il est le plus souvent la victime, le lésé, celui qui a raison.", es: "El ser humano no vive dentro de toda la verdad, sino dentro de la historia que escribe sobre sí mismo: una historia en la que suele ser la víctima, el agraviado, el que tiene la razón.", it: "L'essere umano non vive dentro tutta la verità, ma dentro la storia che scrive su sé stesso: una storia in cui di solito è la vittima, il danneggiato, quello che ha ragione.", pt: "O ser humano não vive dentro de toda a verdade, mas dentro da história que escreve sobre si próprio — uma história em que costuma ser a vítima, o injustiçado, o que tem razão.", nl: "De mens leeft niet in de hele waarheid, maar in het verhaal dat hij over zichzelf schrijft — een verhaal waarin hij meestal het slachtoffer is, de benadeelde, degene die gelijk heeft.", pl: "Człowiek nie żyje w całej prawdzie, lecz w historii, którą pisze o sobie – historii, w której zwykle jest ofiarą, poszkodowanym, tym, kto ma rację.", sv: "Människan lever inte i hela sanningen, utan i den berättelse hon skriver om sig själv – en berättelse där hon oftast är offret, den orättvist behandlade, den som har rätt.", ro: "Omul nu trăiește în tot adevărul, ci în povestea pe care o scrie despre sine – o poveste în care, de obicei, el este victima, cel nedreptățit, cel care are dreptate.", el: "Ο άνθρωπος δεν ζει μέσα σε ολόκληρη την αλήθεια, αλλά μέσα στην ιστορία που γράφει για τον εαυτό του — μια ιστορία όπου συνήθως είναι το θύμα, ο αδικημένος, αυτός που έχει δίκιο.", uk: "Людина живе не в усій правді, а в історії, яку пише про себе, — історії, де вона зазвичай жертва, скривджений, той, хто має рацію.", ru: "Человек живёт не внутри всей правды, а внутри истории, которую пишет о себе, — истории, где он чаще всего жертва, обиженный, тот, кто прав.", tr: "İnsan gerçeğin tamamının içinde yaşamaz; kendisi hakkında yazdığı hikâyenin içinde yaşar — çoğunlukla kurbanın, haksızlığa uğrayanın, haklı olanın olduğu bir hikâye." },
  { slug: "i-am-not-innocent", ar: "أصعب شيء على الإنسان أن يرى دوره الحقيقي في الكارثة. فمن السهل أن نرى أخطاء الآخرين، لكن رؤية أخطائنا تحتاج إلى شجاعة نادرة.", en: "The hardest thing for a person is to see his real part in the disaster. It is easy to see the mistakes of others, but seeing our own takes rare courage.", de: "Das Schwerste für den Menschen ist, seine wahre Rolle in der Katastrophe zu erkennen. Die Fehler der anderen zu sehen ist leicht, aber die eigenen zu sehen erfordert seltenen Mut.", fr: "Le plus difficile pour l'être humain est de voir son vrai rôle dans la catastrophe. Il est facile de voir les erreurs des autres, mais voir les siennes demande un courage rare.", es: "Lo más difícil para una persona es ver su verdadero papel en el desastre. Es fácil ver los errores ajenos, pero ver los propios requiere un valor poco común.", it: "La cosa più difficile per una persona è vedere il proprio vero ruolo nel disastro. È facile vedere gli errori degli altri, ma vedere i propri richiede un coraggio raro.", pt: "O mais difícil para uma pessoa é ver o seu verdadeiro papel no desastre. É fácil ver os erros dos outros, mas ver os nossos exige uma coragem rara.", nl: "Het moeilijkste voor een mens is zijn werkelijke aandeel in de ramp te zien. De fouten van anderen zijn makkelijk te zien, maar de eigen zien vraagt zeldzame moed.", pl: "Najtrudniej jest człowiekowi zobaczyć swoją prawdziwą rolę w katastrofie. Łatwo dostrzec cudze błędy, ale zobaczenie własnych wymaga rzadkiej odwagi.", sv: "Det svåraste för en människa är att se sin verkliga del i katastrofen. Det är lätt att se andras fel, men att se sina egna kräver sällsynt mod.", ro: "Cel mai greu pentru un om este să-și vadă adevăratul rol în dezastru. Este ușor să vezi greșelile altora, dar a le vedea pe ale tale cere un curaj rar.", el: "Το πιο δύσκολο για τον άνθρωπο είναι να δει τον πραγματικό του ρόλο στην καταστροφή. Είναι εύκολο να βλέπουμε τα λάθη των άλλων, αλλά το να βλέπουμε τα δικά μας απαιτεί σπάνιο θάρρος.", uk: "Найважче для людини — побачити свою справжню роль у катастрофі. Легко бачити чужі помилки, але побачити власні потребує рідкісної мужності.", ru: "Труднее всего человеку увидеть свою настоящую роль в катастрофе. Легко видеть чужие ошибки, но увидеть свои требует редкого мужества.", tr: "İnsan için en zoru, felaketteki gerçek payını görmektir. Başkalarının hatalarını görmek kolaydır, ama kendi hatalarımızı görmek ender bir cesaret ister." },
  { slug: "i-am-not-innocent", ar: "فالإنسان لا يغيّر أفعاله أولًا، بل يغيّر الكلمات التي يصف بها تلك الأفعال. ومن هنا تبدأ واحدة من أخطر العمليات النفسية التي يمكن أن تحدث.", en: "A person does not change his actions first; he changes the words with which he describes them. From here begins one of the most dangerous psychological processes there is.", de: "Der Mensch ändert nicht zuerst seine Taten, sondern die Worte, mit denen er sie beschreibt. Hier beginnt einer der gefährlichsten psychologischen Vorgänge überhaupt.", fr: "L'être humain ne change pas d'abord ses actes, il change les mots avec lesquels il les décrit. C'est ici que commence l'un des processus psychologiques les plus dangereux qui soient.", es: "El ser humano no cambia primero sus actos, sino las palabras con las que los describe. Aquí comienza uno de los procesos psicológicos más peligrosos que existen.", it: "L'essere umano non cambia prima le proprie azioni, ma le parole con cui le descrive. Da qui comincia uno dei processi psicologici più pericolosi che esistano.", pt: "O ser humano não muda primeiro as suas ações, mas as palavras com que as descreve. É aqui que começa um dos processos psicológicos mais perigosos que existem.", nl: "De mens verandert niet eerst zijn daden, maar de woorden waarmee hij ze beschrijft. Hier begint een van de gevaarlijkste psychologische processen die er zijn.", pl: "Człowiek nie zmienia najpierw swoich czynów, lecz słowa, którymi je opisuje. Tu zaczyna się jeden z najniebezpieczniejszych procesów psychologicznych.", sv: "Människan ändrar inte först sina handlingar, utan orden hon beskriver dem med. Här börjar en av de farligaste psykologiska processerna som finns.", ro: "Omul nu își schimbă mai întâi faptele, ci cuvintele cu care le descrie. De aici începe unul dintre cele mai periculoase procese psihologice.", el: "Ο άνθρωπος δεν αλλάζει πρώτα τις πράξεις του, αλλά τις λέξεις με τις οποίες τις περιγράφει. Από εδώ ξεκινά μία από τις πιο επικίνδυνες ψυχολογικές διαδικασίες.", uk: "Людина змінює не спочатку свої вчинки, а слова, якими їх описує. Звідси починається один із найнебезпечніших психологічних процесів.", ru: "Человек меняет не сначала свои поступки, а слова, которыми их описывает. Отсюда начинается один из самых опасных психологических процессов.", tr: "İnsan önce eylemlerini değiştirmez; onları anlatırken kullandığı sözcükleri değiştirir. En tehlikeli psikolojik süreçlerden biri buradan başlar." },
  { slug: "i-am-not-innocent", ar: "ولهذا لا يبدأ الشر غالبًا بالفعل، بل بالكلمة التي تسبقه. بالاسم الجديد الذي نعطيه للفعل، وبالقصة التي نجعلها أكثر أهمية من الحقيقة.", en: "That is why evil rarely begins with the deed, but with the word that precedes it — with the new name we give the act, and the story we make more important than the truth.", de: "Darum beginnt das Böse meistens nicht mit der Tat, sondern mit dem Wort, das ihr vorausgeht – mit dem neuen Namen, den wir der Tat geben, und mit der Geschichte, die wir wichtiger machen als die Wahrheit.", fr: "C'est pourquoi le mal commence rarement par l'acte, mais par le mot qui le précède — par le nouveau nom que nous donnons à l'acte, et par l'histoire que nous rendons plus importante que la vérité.", es: "Por eso el mal rara vez empieza con el acto, sino con la palabra que lo precede: con el nuevo nombre que damos al acto y con la historia que hacemos más importante que la verdad.", it: "Per questo il male raramente comincia con l'atto, ma con la parola che lo precede: con il nuovo nome che diamo all'atto e con la storia che rendiamo più importante della verità.", pt: "Por isso o mal raramente começa com o ato, mas com a palavra que o antecede — com o novo nome que damos ao ato e com a história que tornamos mais importante do que a verdade.", nl: "Daarom begint het kwaad zelden met de daad, maar met het woord dat eraan voorafgaat — met de nieuwe naam die we aan de daad geven en het verhaal dat we belangrijker maken dan de waarheid.", pl: "Dlatego zło rzadko zaczyna się od czynu, lecz od słowa, które go poprzedza – od nowej nazwy, którą nadajemy czynowi, i od historii, którą czynimy ważniejszą od prawdy.", sv: "Därför börjar det onda sällan med handlingen, utan med ordet som föregår den – med det nya namnet vi ger handlingen, och berättelsen vi gör viktigare än sanningen.", ro: "De aceea răul începe rareori cu fapta, ci cu cuvântul care o precede – cu numele nou pe care îl dăm faptei și cu povestea pe care o facem mai importantă decât adevărul.", el: "Γι' αυτό το κακό σπάνια ξεκινά με την πράξη, αλλά με τη λέξη που προηγείται — με το νέο όνομα που δίνουμε στην πράξη και με την ιστορία που κάνουμε πιο σημαντική από την αλήθεια.", uk: "Тому зло рідко починається з вчинку, а зі слова, що йому передує, — з нової назви, яку ми даємо вчинку, й історії, яку робимо важливішою за правду.", ru: "Поэтому зло редко начинается с поступка, а со слова, которое ему предшествует, — с нового имени, которое мы даём поступку, и с истории, которую делаем важнее правды.", tr: "Bu yüzden kötülük çoğu zaman eylemle değil, ondan önce gelen sözcükle başlar — eyleme verdiğimiz yeni adla ve gerçekten daha önemli kıldığımız hikâyeyle." },
  { slug: "i-am-not-innocent", ar: "فالنية الحسنة لا تمنع الخطأ دائمًا، والقناعة لا تجعل الإنسان محقًا دائمًا. والإخلاص لفكرة ما لا يحولها تلقائيًا إلى حقيقة.", en: "A good intention does not always prevent a mistake, and conviction does not always make a person right. Devotion to an idea does not automatically turn it into truth.", de: "Eine gute Absicht verhindert nicht immer den Fehler, und Überzeugung macht den Menschen nicht immer zum Recht-Habenden. Hingabe an eine Idee macht sie nicht automatisch zur Wahrheit.", fr: "Une bonne intention n'empêche pas toujours l'erreur, et la conviction ne donne pas toujours raison. La dévotion à une idée ne la transforme pas automatiquement en vérité.", es: "Una buena intención no siempre evita el error, y la convicción no siempre da la razón. La devoción a una idea no la convierte automáticamente en verdad.", it: "Una buona intenzione non impedisce sempre l'errore, e la convinzione non rende sempre ragione. La devozione a un'idea non la trasforma automaticamente in verità.", pt: "Uma boa intenção nem sempre evita o erro, e a convicção nem sempre dá razão. A devoção a uma ideia não a transforma automaticamente em verdade.", nl: "Een goede bedoeling voorkomt niet altijd een fout, en overtuiging maakt je niet altijd gelijk. Toewijding aan een idee maakt er niet automatisch waarheid van.", pl: "Dobra intencja nie zawsze zapobiega błędowi, a przekonanie nie zawsze daje rację. Oddanie idei nie zamienia jej automatycznie w prawdę.", sv: "En god avsikt förhindrar inte alltid ett misstag, och övertygelse gör inte alltid en människa rätt. Hängivenhet åt en idé förvandlar den inte automatiskt till sanning.", ro: "O intenție bună nu previne întotdeauna greșeala, iar convingerea nu îl face mereu pe om să aibă dreptate. Devotamentul față de o idee nu o transformă automat în adevăr.", el: "Μια καλή πρόθεση δεν αποτρέπει πάντα το λάθος και η πεποίθηση δεν δίνει πάντα δίκιο. Η αφοσίωση σε μια ιδέα δεν τη μετατρέπει αυτόματα σε αλήθεια.", uk: "Добрий намір не завжди запобігає помилці, а переконаність не завжди робить людину правою. Відданість ідеї не перетворює її автоматично на істину.", ru: "Добрые намерения не всегда предотвращают ошибку, а убеждённость не всегда делает человека правым. Преданность идее не превращает её автоматически в истину.", tr: "İyi niyet hatayı her zaman önlemez, inanç da insanı her zaman haklı çıkarmaz. Bir fikre bağlılık onu kendiliğinden gerçeğe dönüştürmez." },
  { slug: "i-am-not-innocent", ar: "فأكثر البشر أمانًا ليسوا الذين يخطئون أقل، بل الذين يراجعون أنفسهم أكثر. الذين ما زالوا قادرين على الشك في قصصهم الخاصة.", en: "The safest people are not those who err the least, but those who examine themselves the most — those who are still able to doubt their own stories.", de: "Die verlässlichsten Menschen sind nicht jene, die weniger Fehler machen, sondern jene, die sich öfter selbst hinterfragen – die noch fähig sind, an ihren eigenen Geschichten zu zweifeln.", fr: "Les gens les plus sûrs ne sont pas ceux qui se trompent le moins, mais ceux qui s'examinent le plus — ceux qui sont encore capables de douter de leurs propres histoires.", es: "Las personas más seguras no son las que se equivocan menos, sino las que más se examinan: las que aún son capaces de dudar de sus propias historias.", it: "Le persone più affidabili non sono quelle che sbagliano meno, ma quelle che si interrogano di più: quelle che sono ancora capaci di dubitare delle proprie storie.", pt: "As pessoas mais seguras não são as que erram menos, mas as que mais se examinam — as que ainda são capazes de duvidar das suas próprias histórias.", nl: "De betrouwbaarste mensen zijn niet degenen die het minst falen, maar degenen die zichzelf het meest onderzoeken — degenen die nog aan hun eigen verhalen kunnen twijfelen.", pl: "Najbardziej godni zaufania nie są ci, którzy błądzą najmniej, lecz ci, którzy najczęściej siebie sprawdzają – ci, którzy wciąż potrafią wątpić we własne historie.", sv: "De tryggaste människorna är inte de som felar minst, utan de som granskar sig själva mest – de som fortfarande kan tvivla på sina egna berättelser.", ro: "Cei mai demni de încredere nu sunt cei care greșesc cel mai puțin, ci cei care se cercetează cel mai mult – cei care mai pot să se îndoiască de propriile povești.", el: "Οι πιο αξιόπιστοι άνθρωποι δεν είναι αυτοί που σφάλλουν λιγότερο, αλλά αυτοί που αυτοελέγχονται περισσότερο — αυτοί που μπορούν ακόμη να αμφιβάλλουν για τις δικές τους ιστορίες.", uk: "Найнадійніші люди — не ті, хто помиляється найменше, а ті, хто найбільше перевіряє себе, — ті, хто ще здатен сумніватися у власних історіях.", ru: "Самые надёжные люди — не те, кто меньше ошибается, а те, кто больше проверяет себя, — те, кто ещё способен сомневаться в собственных историях.", tr: "En güvenilir insanlar en az hata yapanlar değil, kendilerini en çok sorgulayanlardır — kendi hikâyelerinden hâlâ kuşku duyabilenler." },
  { slug: "i-am-not-innocent", ar: "لم يعد يحاسب صاحبه، بل أصبح يدافع عنه ويبحث له عن الأعذار.", en: "It no longer holds its owner to account; it has become his defender, searching for excuses on his behalf.", de: "Es zieht seinen Besitzer nicht mehr zur Rechenschaft, sondern verteidigt ihn und sucht Entschuldigungen für ihn.", fr: "Elle ne demande plus de comptes à son propriétaire ; elle est devenue son avocate, cherchant des excuses pour lui.", es: "Ya no pide cuentas a su dueño; se ha convertido en su defensor y le busca excusas.", it: "Non chiede più conto al suo padrone; è diventato il suo difensore, e cerca scuse per lui.", pt: "Já não pede contas ao seu dono; tornou-se o seu defensor, à procura de desculpas por ele.", nl: "Het roept zijn bezitter niet meer ter verantwoording; het is zijn verdediger geworden en zoekt excuses voor hem.", pl: "Nie rozlicza już swego właściciela, lecz stał się jego obrońcą i szuka dla niego usprawiedliwień.", sv: "Det ställer inte längre sin ägare till svars; det har blivit hans försvarare och letar efter ursäkter åt honom.", ro: "Nu își mai trage la răspundere stăpânul; a devenit apărătorul lui, căutându-i scuze.", el: "Δεν ζητά πια λογαριασμό από τον κάτοχό του· έγινε ο υπερασπιστής του και ψάχνει δικαιολογίες γι' αυτόν.", uk: "Воно більше не притягає свого власника до відповідальності, а стало його захисником і шукає для нього виправдання.", ru: "Она больше не призывает своего хозяина к ответу, а стала его защитницей и ищет ему оправдания.", tr: "Artık sahibini hesaba çekmiyor; onun savunucusu olmuş, onun için bahaneler arıyor." },
  { slug: "i-am-not-innocent", ar: "وفي تلك اللحظة لم يعد السؤال: ماذا كنت أقصد؟ بل: ماذا تركت خلفي؟", en: "In that moment the question was no longer: What did I mean? But: What did I leave behind?", de: "In diesem Augenblick lautete die Frage nicht mehr: Was habe ich gemeint? Sondern: Was habe ich hinterlassen?", fr: "À cet instant, la question n'était plus : qu'est-ce que je voulais dire ? Mais : qu'ai-je laissé derrière moi ?", es: "En ese momento la pregunta ya no era: ¿qué quise decir? Sino: ¿qué dejé atrás?", it: "In quel momento la domanda non era più: che cosa intendevo? Ma: che cosa mi sono lasciato alle spalle?", pt: "Naquele momento a pergunta já não era: o que quis eu dizer? Mas: o que deixei para trás?", nl: "Op dat moment was de vraag niet langer: wat bedoelde ik? Maar: wat liet ik achter?", pl: "W tamtej chwili pytanie brzmiało już nie: co miałem na myśli? Lecz: co po sobie zostawiłem?", sv: "I det ögonblicket var frågan inte längre: Vad menade jag? Utan: Vad lämnade jag efter mig?", ro: "În acel moment întrebarea nu mai era: ce am vrut să spun? Ci: ce am lăsat în urmă?", el: "Εκείνη τη στιγμή η ερώτηση δεν ήταν πια: τι εννοούσα; Αλλά: τι άφησα πίσω μου;", uk: "У ту мить питання було вже не: що я мав на увазі? А: що я залишив по собі?", ru: "В тот миг вопрос был уже не: что я имел в виду? А: что я оставил после себя?", tr: "O anda soru artık şu değildi: Ne demek istemiştim? Şuydu: Geride ne bıraktım?" },
];
